def maxAreaOfIsland(grid: list[list[int]]) -> int:
    R, C = len(grid), len(grid[0])
    def dfs(r, c):
        if 0 <= r < R and 0 <= c < C and grid[r][c] == 1:
            grid[r][c] = 0
            return 1 + dfs(r + 1, c) + dfs(r - 1, c) + dfs(r, c + 1) + dfs(r, c - 1)
        return 0
    ans = 0
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 1:
                ans = max(ans, dfs(r, c))
    return ans

